    // Event Listeners
    sendBtn.addEventListener('click', sendBusinessMessage);

    replyInput.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') sendBusinessMessage();
    });

    customerTriggers.forEach(btn => {
      btn.addEventListener('click', (e) => {
        const messageText = e.currentTarget.getAttribute('data-message');
        sendCustomerMessage(messageText);
      });
    });

    exportBtn.addEventListener('click', exportTranscript);
  });
</script>
</body>
</html>

